import {FirebaseService,configured,friendlyError} from './service.js';
import {DemoService} from './demo.js';
import {esc,money,today,shiftDay,dateLabel,link,download,toCSV,toICS,statusLabels,kindLabels,daysUntil,urgency} from './helpers.js';
import {schemas,statuses} from './schema.js';

const root=document.querySelector('#app');
const state={service:null,demo:false,user:null,snapshot:null,route:'home',search:'',subject:'',showArchive:false,semester:'',month:today().slice(0,7),calendarView:'month',weekStart:shiftDay(today(),-((new Date(today()+'T12:00:00Z').getUTCDay()+6)%7)),loading:false,epoch:0};
const nav=[['home','⌂','Visão geral'],['notices','▤','Mural de avisos'],['calendar','▦','Calendário'],['subjects','▧','Matérias e estudos'],['schedules','◷','Horários de aula'],['teachers','♧','Professores'],['finance','◇','Caixa da turma'],['requests','↗','Solicitações'],['favorites','☆','Meus favoritos'],['help','?','Ajuda da turma']];
const data=()=>state.snapshot?.data||{};
const items=e=>data()[e]||[];
const me=()=>state.snapshot?.me||{};
const admin=()=>['owner','admin'].includes(me().role);
const owner=()=>me().role==='owner';
const personal=()=>state.snapshot?.personal||{favorites:[],tasks:{},read:{},preferences:{}};
const item=(e,id)=>items(e).find(x=>x.id===id);
const titleFor=(e,id)=>item(e,id)?.title||'';
const uid=()=>crypto.randomUUID();
const roles={owner:'Responsável principal',admin:'Administrador',student:'Aluno'};
const weekdays={'1':'Segunda-feira','2':'Terça-feira','3':'Quarta-feira','4':'Quinta-feira','5':'Sexta-feira','6':'Sábado'};
const requestTypes={notice:'Aviso',event:'Evento ou prazo',material:'Material de estudo',group:'Grupo de estudo',correction:'Correção ou remoção',finance:'Comprovante ou caixa',support:'Ajuda ou erro'};
function button(label,action,attrs='',kind='secondary'){return `<button type="button" class="btn btn-${kind}" data-action="${action}" ${attrs}>${label}</button>`;}
function badge(s){return `<span class="badge ${['pending','awaiting','draft'].includes(s)?'badge-warning':['cancelled','rejected'].includes(s)?'badge-danger':''}">${esc(statusLabels[s]||s)}</span>`;}
function empty(text='Nenhum registro por aqui.',action=''){return `<div class="empty"><span class="empty-symbol">◇</span><h3>${esc(text)}</h3><p class="muted">As informações publicadas para sua turma aparecerão aqui.</p>${action}</div>`;}
function visible(entity){return items(entity).filter(x=>(state.showArchive||x.status!=='archived')&&(!state.category||!["notices","materials","events"].includes(entity)||(x.category||x.kind)===state.category)&&(!state.fromDate||!(x.date||x.createdAt)||(x.date||x.createdAt).slice(0,10)>=state.fromDate)&&(!state.toDate||!(x.date||x.createdAt)||(x.date||x.createdAt).slice(0,10)<=state.toDate)&&(!state.subject||!x.subjectId||x.subjectId===state.subject)&&(!state.search||[x.title,x.description,x.category,titleFor('subjects',x.subjectId)].join(' ').toLocaleLowerCase('pt-BR').includes(state.search.toLocaleLowerCase('pt-BR'))));}
function countVisible(e){return items(e).filter(x=>x.status==='published').length;}
function toast(text,bad=false){document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast '+(bad?'error':'success');d.setAttribute('role','status');d.textContent=text;document.body.append(d);setTimeout(()=>d.remove(),6500);}
function loading(text='Carregando a turma…'){root.innerHTML=`<div class="login-page"><div class="card loading"><span class="spinner"></span><p>${esc(text)}</p></div></div>`;}
function heading(title,subtitle='',actions=''){return `<div class="page-heading"><div><p class="eyebrow">ESPAÇO DA TURMA</p><h1>${esc(title)}</h1><p class="muted">${esc(subtitle)}</p></div><div class="actions">${actions}</div></div>`;}
function adminNew(e){return admin()?button('+ '+schemas[e].label,'edit',`data-entity="${e}"`,'primary'):'';}
function more(e){return state.snapshot?.more?.[e]?button('Carregar mais','more',`data-entity="${e}"`):'';}
function filters(){const categories=[...new Set([...items('notices').map(x=>x.category),...items('materials').map(x=>x.category),...items('events').map(x=>x.kind)].filter(Boolean))];return `<div class="toolbar"><label class="field"><span class="sr-only">Filtrar matéria</span><select id="subject-filter"><option value="">Todas as matérias</option>${items('subjects').filter(x=>x.status!=='archived').map(x=>`<option value="${esc(x.id)}" ${x.id===state.subject?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label class="field"><span class="sr-only">Categoria ou tipo</span><select id="category-filter"><option value="">Todas as categorias</option>${categories.map(x=>`<option ${state.category===x?'selected':''} value="${esc(x)}">${esc(kindLabels[x]||x)}</option>`).join('')}</select></label><label class="field">De<input id="from-date" type="date" value="${esc(state.fromDate||'')}"></label><label class="field">Até<input id="to-date" type="date" value="${esc(state.toDate||'')}"></label>${admin()?`<label class="check"><input id="archive-filter" type="checkbox" ${state.showArchive?'checked':''}> Arquivados</label>`:''}${button('Limpar filtros','clear-filters','','ghost')}</div>`;}

function favorite(e,id){const active=(personal().favorites||[]).includes(e+'/'+id);return button(active?'★ Salvo':'☆ Salvar','favorite',`data-entity="${e}" data-id="${esc(id)}"`,'ghost');}
function recordActions(e,x){return `<div class="actions">${['notices','materials','events','groups'].includes(e)?favorite(e,x.id):''}${button('Ver detalhes','detail',`data-entity="${e}" data-id="${esc(x.id)}"`,'ghost')}${admin()?button('Editar','edit',`data-entity="${e}" data-id="${esc(x.id)}"`,'ghost'):''}</div>`;}
function recordCard(e,x){const subtitle=e==='events'?`${kindLabels[x.kind]||'Evento'} · ${dateLabel(x.date)}${x.time?' às '+x.time:x.allDay?' · Dia inteiro':' · Horário não informado'}`:e==='groups'?`${dateLabel(x.date)} ${x.time||''}`:titleFor('subjects',x.subjectId)||x.category||'Turma';return `<article class="card ${x.pinned?'pinned':''}"><div class="card-header"><span class="eyebrow">${esc(subtitle)}</span>${badge(x.status)}</div><h3>${esc(x.title)}</h3><p class="item-body">${esc((x.description||'').slice(0,400))}</p><div class="metadata">${x.authorName?`Por ${esc(x.authorName)} · `:''}${x.createdAt?'Atualizado '+dateLabel(x.updatedAt||x.createdAt):''}</div>${link(x.sourceUrl)}${recordActions(e,x)}</article>`;}

function loginView(message=''){
 root.innerHTML=`<main class="login-page" id="main-content"><section class="login-story"><a class="brand"><span class="brand-mark">t.</span><span>entre aulas<span class="brand-caption">PORTAL DA TURMA</span></span></a><p class="eyebrow">LICENCIATURA · NOSSO ESPAÇO</p><h1>Uma turma.<br>Todos os caminhos<br>no mesmo lugar.</h1><p>Avisos, entregas e conhecimento compartilhado. Mais organização para aprender juntos.</p><div class="login-pills"><span>Calendário</span><span>Estudos</span><span>Caixa da turma</span></div><p class="footer-note">Acesso exclusivo para integrantes autorizados.</p></section><section class="login-card"><p class="eyebrow">BEM-VINDO DE VOLTA</p><h2>Entre na sua turma</h2><p class="muted">Use o e-mail autorizado pelo responsável.</p>${message?`<div class="error" role="alert">${esc(message)}</div>`:''}${!configured?`<div class="notice">O Firebase ainda não foi configurado. Siga o arquivo LEIA-ME para conectar sua turma.</div>`:''}<form id="login-form" class="login-form"><label class="field">E-mail<input name="email" type="email" autocomplete="email" required placeholder="seu@email.com"></label><label class="field">Senha<input name="password" type="password" autocomplete="current-password" minlength="8" required placeholder="Sua senha"></label><button class="btn btn-primary" ${!configured?'disabled':''}>Entrar na turma →</button></form><div class="login-actions">${button('Esqueci minha senha','reset')}${button('Criar minha conta','signup')}</div><div class="divider">ou</div>${button('Continuar com Google','google',!configured?'disabled':'','secondary')}<div class="demo-banner"><strong>Conheça o portal</strong><p>Teste com dados fictícios. Nada é enviado ao Firebase.</p>${button('Abrir demonstração','demo','','ghost')}</div></section></main>`;
}
function gateView(message){root.innerHTML=`<main class="login-page" id="main-content"><section class="login-card"><span class="brand-mark">t.</span><h1>Quase lá</h1><p>${esc(message)}</p><p class="muted">${esc(state.user?.email||'')}</p><div class="actions">${button('Já confirmei / tentar novamente','retry','','primary')}${state.user&&!state.user.emailVerified?button('Reenviar verificação','resend'):''}${button('Sair','logout')}</div><p class="form-note">A conta precisa ter e-mail verificado e convite do responsável pela turma.</p></section></main>`;}

async function startFirebase(){const service=new FirebaseService();state.service=service;await service.init(async user=>{if(state.service!==service||state.demo)return;state.epoch++;state.loading=false;state.user=user;state.snapshot=null;document.querySelector('dialog')?.close();if(!user){state.semester='';state.search='';state.subject='';loginView();return;}if(!user.emailVerified){gateView('Confirme seu e-mail pelo link enviado para liberar a entrada.');return;}await load(true);});}
async function load(full=false,force=false){
 if(state.loading)return;state.loading=true;const epoch=state.epoch,service=state.service;if(full)loading();
 try{
  const snapshot=await service.call('bootstrap',{...(state.semester?{semesterId:state.semester}:{}),view:location.hash.split('/')[1]||'home',force});
  const semester=state.semester||snapshot.settings.activeSemesterId||'';
  if(epoch!==state.epoch||service!==state.service)return;
  if(!location.hash&&snapshot.personal?.preferences?.initialView)location.hash='#/'+snapshot.personal.preferences.initialView;
  if(!state.snapshot&&snapshot.personal?.preferences?.subjectId)state.subject=snapshot.personal.preferences.subjectId;
  snapshot.data.news.sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));
  state.snapshot=snapshot;state.semester=semester;
  document.body.dataset.theme=personal().preferences?.theme||'light';render();
 }catch(e){if(epoch!==state.epoch||service!==state.service)return;if(full||!state.snapshot||['permission-denied','unauthenticated','functions/permission-denied','functions/unauthenticated'].includes(e.code)){state.snapshot=null;document.querySelector('dialog')?.close();gateView(friendlyError(e));}else toast(friendlyError(e),true);}
 finally{if(epoch===state.epoch)state.loading=false;}
}
function render(){if(!state.snapshot)return;const settings=state.snapshot.settings;state.route=location.hash.split('/')[1]||'home';const navigation=[...nav,...(admin()?[['admin','⚙','Gestão da turma']]:[])];const label=navigation.find(x=>x[0]===state.route)?.[2]||'Portal';
 root.innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#/home"><span class="brand-mark">t.</span><span>${esc(settings.title||'entre aulas')}<span class="brand-caption">${esc(settings.course||'LICENCIATURA')}</span></span></a><p class="sidebar-label">NOSSO ESPAÇO</p><nav class="nav-list" aria-label="Menu principal">${navigation.map(([r,i,l])=>`<a href="#/${r}" class="nav-link ${state.route===r?'active':''}"><span aria-hidden="true">${i}</span>${l}${r==='requests'&&admin()&&(!state.snapshot.loaded||state.snapshot.loaded.includes('requests'))?`<small>${items('requests').filter(x=>['pending','reviewing','awaiting'].includes(x.status)).length}</small>`:''}</a>`).join('')}</nav><div class="sidebar-footer"><div class="avatar">${esc((me().name||'T')[0])}</div><div><strong>${esc(me().name||'Integrante')}</strong><span>${roles[me().role]||'Aluno'}</span></div>${button('Sair','logout','','ghost')}</div></aside><main class="main" id="main-content"><header class="topbar"><button class="icon-btn mobile-menu" aria-label="Abrir menu" data-action="menu">☰</button><span class="topbar-title">${esc(settings.university||'Licenciatura · Portal da turma')}</span><div class="topbar-actions"><select id="semester-select" aria-label="Semestre"><option value="">Semestre ativo</option>${items('semesters').map(x=>`<option value="${esc(x.id)}" ${x.id===state.semester?'selected':''}>${esc(x.title)}</option>`).join('')}</select>${button('↻ Atualizar','refresh','','ghost')}${button(personal().preferences?.theme==='dark'?'☀':'☾','theme','aria-label="Alternar tema"','ghost')}</div></header>${state.demo?`<div class="demo-banner"><strong>DEMONSTRAÇÃO · Dados fictícios no seu navegador</strong><select id="demo-role" aria-label="Perfil de demonstração"><option value="owner" ${me().role==='owner'?'selected':''}>Responsável</option><option value="admin" ${me().role==='admin'?'selected':''}>Administrador</option><option value="student" ${me().role==='student'?'selected':''}>Aluno</option></select>${button('Reiniciar dados','reset-demo','','ghost')}</div>`:''}<div class="page-content"><div class="toolbar searchbar"><label class="search"><span aria-hidden="true">⌕</span><input id="global-search" type="search" value="${esc(state.search)}" placeholder="Buscar nos registros carregados…" aria-label="Buscar registros"></label><span class="muted">${esc(dateLabel(today()))}</span></div><div id="content"></div>${Object.entries(state.snapshot.more||{}).some(([e,c])=>c&&['semesters','subjects','teachers','schedules','events','notices','news','goals','members','materials','groups','requests','audit','invites'].includes(e))?`<div class="notice">Há mais registros além do limite de carregamento inicial. Calendário, busca e contadores consideram os registros carregados.<div class="actions">${Object.entries(state.snapshot.more).filter(([e,c])=>c&&['semesters','subjects','teachers','schedules','events','notices','news','goals','members','materials','groups','requests','audit','invites'].includes(e)).map(([e])=>button('Carregar mais: '+(schemas[e]?.label||{requests:'Solicitações',audit:'Histórico',members:'Participantes',invites:'Convites',news:'Mudanças de prazo'}[e]||e),'more',`data-entity="${e}"`)).join('')}</div></div>`:''}<p class="footer-note">Informações organizadas pela turma. Confira os detalhes e as entregas na fonte original.</p></div></main></div>`;
 renderContent();
 const [,route,id]=location.hash.split('/');if(id&&schemas[route]&&item(route,id))detail(route,id);
}
function renderContent(){const el=document.querySelector('#content');if(!el)return;const views={home:homeView,notices:()=>listView('notices','Mural de avisos','Comunicados que ajudam a turma a seguir junta.'),calendar:calendarView,subjects:subjectsView,schedules:schedulesView,teachers:teachersView,finance:financeView,requests:requestsView,favorites:favoritesView,help:helpView,admin:adminView,events:calendarView,materials:subjectsView,groups:subjectsView};el.innerHTML=(views[state.route]||homeView)();}
function homeView(){const events=items('events').filter(x=>x.status==='published'&&x.eventState!=='completed'&&daysUntil(x.date)>=0).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')));const next=events.filter(x=>daysUntil(x.date)<=7);const tasks=personal().tasks||{};return heading(`Olá, ${(me().name||'turma').split(' ')[0]} ☀`,'Seu semestre, com mais clareza e menos correria.',button('+ Enviar solicitação','request','','primary'))+`<section class="hero card"><div><p class="eyebrow">VAMOS ORGANIZAR A SEMANA</p><h2>O que vem por aí?</h2><p>Há ${next.length} evento${next.length===1?'':'s'} nos próximos 7 dias entre os registros carregados.</p><a class="btn btn-primary" href="#/calendar">Abrir calendário →</a></div><div class="hero-decoration" aria-hidden="true">▦</div></section><div class="grid grid-4"><article class="card stat"><span class="stat-label">PRÓXIMOS 7 DIAS</span><strong class="stat-value">${next.length}</strong><span class="stat-note">Provas e atividades</span></article><article class="card stat"><span class="stat-label">MATÉRIAS</span><strong class="stat-value">${countVisible('subjects')}</strong><span class="stat-note">Neste semestre</span></article><article class="card stat"><span class="stat-label">MEU PROGRESSO</span><strong class="stat-value">${Object.values(tasks).filter(x=>x==='done').length}</strong><span class="stat-note">Atividades marcadas concluídas</span></article><article class="card stat"><span class="stat-label">CAIXA DA TURMA</span><strong class="stat-value">${money(state.snapshot.totals?.balanceCents)}</strong><span class="stat-note">Saldo total confirmado</span></article></div><div class="grid grid-2"><section><div class="section-heading"><h2>Próximos prazos</h2><a href="#/calendar" class="link">Ver agenda →</a></div><div class="list">${events.slice(0,6).map(x=>`<article class="card list-item"><div class="date-tile"><strong>${x.date.slice(8)}</strong><span>${new Date(x.date+'T12:00:00Z').toLocaleDateString('pt-BR',{month:'short'})}</span></div><div><span class="badge ${daysUntil(x.date)<=1?'badge-warning':''}">${urgency(x)}</span><h3>${esc(x.title)}</h3><p class="metadata">${esc(titleFor('subjects',x.subjectId))} · ${x.time||'Horário não informado'}</p></div>${button('↗','detail',`data-entity="events" data-id="${esc(x.id)}" aria-label="Ver evento"`,'ghost')}</article>`).join('')||empty('Nenhum prazo próximo.')}</div></section><section><div class="section-heading"><h2>No mural</h2><a href="#/notices" class="link">Todos os avisos →</a></div>${items('notices').filter(x=>x.status==='published'&&(!x.expiresDate||x.expiresDate>=today())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)).slice(0,3).map(x=>recordCard('notices',x)).join('')||empty('A turma ainda não publicou avisos.')}</section></div><section><h2>Últimas mudanças de prazo</h2>${items('news').slice(0,4).map(x=>`<article class="card"><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p>${button('Ver evento','detail',`data-entity="events" data-id="${esc(x.eventId)}"`,'ghost')}</article>`).join('')||'<p class="muted">Nenhuma mudança registrada.</p>'}</section>`;}
function listView(e,title,subtitle){return heading(title,subtitle,adminNew(e))+filters()+`<div class="grid grid-2">${visible(e).sort((a,b)=>Number(b.pinned||0)-Number(a.pinned||0)).map(x=>recordCard(e,x)).join('')||empty('Nenhum conteúdo encontrado.',button('Sugerir uma publicação','request'))}</div>${more(e)}`;}
function calendarView(){
 const events=visible('events').sort((a,b)=>a.date.localeCompare(b.date));const [y,m]=state.month.split('-').map(Number);
 const first=new Date(Date.UTC(y,m-1,1,12));const week=state.calendarView==='week';
 const start=week?state.weekStart:shiftDay(state.month+'-01',-((first.getUTCDay()+6)%7));
 const label=week?`${dateLabel(start)} a ${dateLabel(shiftDay(start,6))}`:first.toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'});
 return heading('Calendário da turma','Provas, entregas e encontros em um só lugar.',adminNew('events')+button('Exportar ICS','ics'))+filters()+`<div class="toolbar">${button('‹','month','data-step="-1"')}<h2>${esc(label)}</h2>${button('›','month','data-step="1"')}${button('Hoje','month-today')}<select id="calendar-view" aria-label="Visualização do calendário">${[['month','Mês'],['week','Semana'],['list','Lista']].map(([v,l])=>`<option value="${v}" ${state.calendarView===v?'selected':''}>${l}</option>`).join('')}</select></div>${state.calendarView!=='list'?`<section class="calendar"><div class="calendar-weekdays">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:week?7:42},(_,n)=>{const date=shiftDay(start,n);return `<div class="calendar-day ${!week&&!date.startsWith(state.month)?'other-month':''} ${date===today()?'today':''}"><span class="day-number">${Number(date.slice(8))}</span>${events.filter(e=>e.date<=date&&(e.endDate||e.date)>=date).map(e=>`<button class="calendar-event ${e.kind==='exam'?'exam':''}" data-action="detail" data-entity="events" data-id="${esc(e.id)}" title="${esc(e.title)}">${esc(e.time||'')} ${esc(e.title)}${e.status==='cancelled'?' · Cancelado':''}${e.eventState==='completed'?' · Concluído':''}</button>`).join('')}</div>`;}).join('')}</div></section>`:`<div class="grid grid-2">${events.map(x=>recordCard('events',x)).join('')||empty('Calendário sem eventos.')}</div>`}${more('events')}<p class="form-note">Fuso: Brasília (America/Sao_Paulo). Datas sem horário são mostradas como horário não informado.</p>`;
}
function subjectsView(){return heading('Matérias e estudos','Anotações, materiais e encontros para aprender juntos.',adminNew('subjects')+adminNew('materials')+adminNew('groups'))+filters()+`<div class="grid grid-3">${visible('subjects').filter(x=>!state.subject||x.id===state.subject).map(x=>`<article class="card subject-card"><span class="subject-dot"></span><h3>${esc(x.title)}</h3><p class="metadata">${(x.teacherIds||[]).map(id=>esc(titleFor('teachers',id))).join(', ')||'Professor a cadastrar'}</p><p>${esc(x.description||'')}</p>${link(x.platformUrl,'Plataforma principal')}${(x.links||[]).map(l=>`<p>${link(l.url,l.label)}</p>`).join('')}<p class="metadata">${x.sourceCheckedDate?'Conferido em '+dateLabel(x.sourceCheckedDate):''}</p><div class="actions">${button('Abrir mural','subject',`data-id="${esc(x.id)}"`,'primary')}${admin()?button('Editar','edit',`data-entity="subjects" data-id="${esc(x.id)}"`):''}</div></article>`).join('')||empty('Cadastre as matérias do semestre.')}</div><div class="section-heading"><h2>${state.subject?'Mural de '+esc(titleFor('subjects',state.subject)):'Materiais de estudo'}</h2>${button('Compartilhar material','request','data-type="material"')}</div><div class="grid grid-2">${visible('materials').map(x=>recordCard('materials',x)).join('')||empty('Nenhum material publicado.')}</div>${more('materials')}<div class="section-heading"><h2>Grupos de estudo</h2>${button('Sugerir grupo','request','data-type="group"')}</div><div class="grid grid-2">${visible('groups').map(x=>recordCard('groups',x)).join('')||empty('Nenhum grupo de estudo publicado.')}</div>${more('groups')}${state.subject?`<h2>Prazos desta matéria</h2><div class="grid grid-2">${visible('events').filter(x=>x.subjectId===state.subject).map(x=>recordCard('events',x)).join('')||'<p class="muted">Nenhum evento.</p>'}</div><h2>Avisos desta matéria</h2><div class="grid grid-2">${visible('notices').filter(x=>x.subjectId===state.subject).map(x=>recordCard('notices',x)).join('')||'<p class="muted">Nenhum aviso.</p>'}</div>`:''}`;}
function schedulesView(){return heading('Horários de aula','Sua semana de aulas, salas e plataformas.',adminNew('schedules'))+filters()+`<div class="grid grid-3">${Object.entries(weekdays).map(([day,label])=>`<section class="card"><h3>${label}</h3>${visible('schedules').filter(x=>String(x.weekday)===day).sort((a,b)=>a.time.localeCompare(b.time)).map(x=>`<div class="schedule-item"><span class="badge">${esc(x.time)} – ${esc(x.endTime)}</span><h4>${esc(titleFor('subjects',x.subjectId)||x.title)}</h4><p class="metadata">${esc(x.room||'Sala não informada')}</p>${link(item('subjects',x.subjectId)?.platformUrl,'Plataforma')}${admin()?button('Editar','edit',`data-entity="schedules" data-id="${esc(x.id)}"`,'ghost'):''}</div>`).join('')||'<p class="muted">Sem aula cadastrada.</p>'}</section>`).join('')}</div>`;}
function teachersView(){return heading('Professores','Contatos acadêmicos e locais de compartilhamento.',adminNew('teachers'))+`<div class="grid grid-3">${visible('teachers').map(x=>`<article class="card"><div class="avatar">${esc(x.title[0])}</div><h3>${esc(x.title)}</h3><p class="metadata">${items('subjects').filter(s=>(s.teacherIds||[]).includes(x.id)).map(s=>esc(s.title)).join(' · ')}</p><p>${esc(x.email||'E-mail não informado')}</p><p>${esc(x.contact||'')}</p><p class="muted">${esc(x.officeHours||'')}</p>${link(x.platformUrl)}${(x.links||[]).map(l=>`<p>${link(l.url,l.label)}</p>`).join('')}<p class="metadata">${x.sourceCheckedDate?'Conferido em '+dateLabel(x.sourceCheckedDate):''}</p><p>${esc(x.description||'')}</p>${recordActions('teachers',x)}</article>`).join('')||empty('Nenhum professor cadastrado.')}</div>${more('teachers')}`;}
function financeView(){const totals=state.snapshot.totals||{};return heading('Caixa da turma','Transparência para cuidar do que é de todos.',(admin()?button('+ Registrar movimento','ledger','','primary')+adminNew('goals'):'')+button('Exportar CSV','csv'))+`<div class="grid grid-3"><article class="card stat"><span class="stat-label">SALDO ATUAL</span><strong class="stat-value">${money(totals.balanceCents)}</strong><span class="stat-note">Todos os movimentos confirmados</span></article><article class="card stat"><span class="stat-label">ENTRADAS LÍQUIDAS</span><strong class="stat-value">${money(totals.incomeCents)}</strong></article><article class="card stat"><span class="stat-label">SAÍDAS LÍQUIDAS</span><strong class="stat-value">${money(totals.expenseCents)}</strong></article></div><h2>Objetivos da turma</h2><div class="grid grid-3">${visible('goals').map(g=>{const total=state.snapshot.goalTotals?.[g.id];const p=Math.max(0,Math.min(100,(total??0)/g.targetCents*100));return `<article class="card"><h3>${esc(g.title)}</h3><p>${esc(g.description||'')}</p><p><strong>${total===undefined?'Saldo não carregado':money(total)}</strong> de ${money(g.targetCents)}</p><progress class="progress" value="${p}" max="100">${p}%</progress><p class="metadata">${g.date?dateLabel(g.date):'Sem prazo'} · Progresso dos movimentos confirmados</p>${admin()?button('Editar meta','edit',`data-entity="goals" data-id="${esc(g.id)}"`,'ghost'):''}</article>`;}).join('')||'<p class="muted">Nenhuma meta cadastrada.</p>'}</div><div class="section-heading"><h2>Movimentos</h2>${button('Enviar comprovante ou dúvida','request','data-type="finance"')}</div><div class="toolbar"><label class="field">Período<input id="ledger-month" type="month" value="${esc(state.ledgerMonth||'')}"></label><span class="form-note">O saldo acima é total. O filtro afeta somente a lista e a exportação.</span></div><div class="table-wrap card"><table><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${visible('ledger').filter(x=>!state.ledgerMonth||x.date.startsWith(state.ledgerMonth)).sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${dateLabel(x.date)}</td><td><strong>${esc(x.title)}</strong>${x.reversalOf?'<span class="badge">Estorno</span>':''}${x.reversedBy?'<span class="badge">Estornado</span>':''}<div class="metadata">${esc(x.description||'')}</div>${link(x.receiptUrl,'Comprovante privado')}</td><td>${esc(x.category||'Geral')}</td><td class="${x.deltaCents>=0?'ledger-positive':'ledger-negative'}">${money(x.deltaCents)}</td><td>${admin()&&!x.reversalOf&&!x.reversedBy?button('Estornar','reverse',`data-id="${esc(x.id)}"`,'ghost'):''}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum movimento neste período.</td></tr>'}</tbody></table></div>${more('ledger')}<p class="form-note">Comprovantes são conferidos pelos administradores. O site não processa pagamentos.</p>`;}
function requestsView(){return heading(admin()?'Solicitações da turma':'Minhas solicitações','Envie contribuições e acompanhe a resposta dos administradores.',button('+ Nova solicitação','request','','primary'))+`<div class="toolbar"><select id="request-kind" aria-label="Tipo do pedido"><option value="">Todos os tipos</option>${Object.entries(requestTypes).map(([k,l])=>`<option value="${k}" ${state.requestKind===k?'selected':''}>${l}</option>`).join('')}</select>${admin()?`<select id="request-owner" aria-label="Responsável pela análise"><option value="">Qualquer responsável</option><option value="unassigned" ${state.requestOwner==='unassigned'?'selected':''}>Sem responsável</option>${items('members').filter(m=>['owner','admin'].includes(m.role)).map(m=>`<option value="${esc(m.id)}" ${state.requestOwner===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`:''}<select id="request-status" aria-label="Filtrar situação"><option value="">Todas as situações</option>${['pending','reviewing','awaiting','approved','rejected','cancelled'].map(s=>`<option value="${s}" ${state.requestStatus===s?'selected':''}>${statusLabels[s]}</option>`).join('')}</select></div><div class="grid grid-2">${visible('requests').filter(x=>(!state.requestStatus||x.status===state.requestStatus)&&(!state.requestKind||x.type===state.requestKind)&&(!state.requestOwner||(state.requestOwner==='unassigned'?!x.reviewedBy:x.reviewedBy===state.requestOwner))).map(x=>`<article class="card"><div class="card-header"><span class="eyebrow">${esc(requestTypes[x.type]||x.type)}</span>${badge(x.status)}</div><h3>${esc(x.title)}</h3><p class="item-body">${esc(x.description)}</p>${link(x.sourceUrl,'Referência enviada')}<p class="metadata">${esc(x.authorName||'Você')} · ${dateLabel(x.createdAt)} · Pedido ${esc(x.id.slice(0,8))}</p>${x.response?`<div class="notice"><strong>Resposta</strong><p>${esc(x.response)}</p></div>`:''}<div class="actions">${admin()&&!['approved','rejected','cancelled'].includes(x.status)?button('Analisar','review',`data-id="${esc(x.id)}"`,'primary'):''}${x.authorId===me().id?button('Enviar complemento','request',`data-parent="${esc(x.id)}" data-type="${esc(x.type)}"`,'ghost'):''}</div>${x.publishedId?'<p class="success">Conteúdo aprovado e vinculado à publicação.</p>':''}</article>`).join('')||empty('Nenhuma solicitação encontrada.')}</div>${more('requests')}`;}
function preferencesForm(){const pref=personal().preferences||{};return `<section class="card"><h2>Minha organização</h2><form data-form="preferences"><div class="form-grid"><label class="field">Tela inicial<select name="initialView">${[['home','Visão geral'],['calendar','Calendário'],['subjects','Matérias']].map(([v,l])=>`<option value="${v}" ${pref.initialView===v?'selected':''}>${l}</option>`).join('')}</select></label>${fieldHTML(['subjectId','Matéria preferida','subjects'],pref.subjectId)}</div><div class="form-error error" hidden></div><div class="actions"><button class="btn btn-primary">Salvar preferências</button>${button('Restaurar padrões','reset-preferences')}</div></form></section>`;}
function favoritesView(){const favs=(personal().favorites||[]).map(key=>{const [entity,id]=key.split('/');return {entity,record:item(entity,id),id};});return heading('Meus favoritos','Seus materiais e avisos salvos, visíveis só para você.')+`<div class="grid grid-2">${favs.map(({entity,record,id})=>record?recordCard(entity,record):`<article class="card"><p>Item de outro semestre, arquivado ou ainda não carregado.</p>${button('Remover favorito','favorite',`data-entity="${esc(entity)}" data-id="${esc(id)}"`)}</article>`).join('')||empty('Salve um aviso ou material para encontrar aqui.')}</div>${preferencesForm()}`;}
function helpView(){return heading('Ajuda da turma','Como usar nosso espaço compartilhado.')+`<article class="card help-content"><h2>Orientações da turma</h2><p class="item-body">${esc(state.snapshot.settings.helpText||'Use o Calendário para consultar prazos. Em Solicitações, envie materiais e informações para os administradores. A publicação acontece após aprovação.')}</p><h3>Como compartilhar material?</h3><p>Abra Solicitações, escolha Material de estudo, indique a matéria e inclua o link. O administrador confere e publica no mural da matéria.</p><h3>O site envia meu trabalho ao professor?</h3><p>A entrega acontece na plataforma indicada pelo professor. O checklist ajuda somente na sua organização.</p><h3>Uma data mudou?</h3><p>Envie uma solicitação com o link da fonte. Administradores corrigem o evento e registram a alteração.</p><h3>Quem pode ver as informações?</h3><p>Somente integrantes autorizados. Solicitações e comprovantes ficam restritos ao autor e à administração. Favoritos e checklist são pessoais.</p>${button('Pedir ajuda','request','data-type="support"','primary')}</article>`;}
function adminView(){if(!admin())return empty('Área exclusiva dos administradores.');return heading('Gestão da turma','Publicações, participantes e organização dos semestres.',button('Configurações','settings')+(owner()?button('Exportar dados da turma','backup')+button('+ Convidar integrante','invite','','primary'):''))+`<div class="grid grid-3"><article class="card stat"><span class="stat-label">PEDIDOS ABERTOS CARREGADOS</span><strong class="stat-value">${items('requests').filter(x=>['pending','reviewing','awaiting'].includes(x.status)).length}</strong><a class="link" href="#/requests">Abrir fila →</a></article><article class="card stat"><span class="stat-label">INTEGRANTES ATIVOS</span><strong class="stat-value">${items('members').filter(x=>x.active).length}</strong><span class="stat-note">Turma planejada para 44 alunos</span></article><article class="card stat"><span class="stat-label">CONVITES</span><strong class="stat-value">${items('invites').length}</strong><span class="stat-note">Entrada por e-mail verificado</span></article></div><div class="section-heading"><h2>Semestres</h2>${adminNew('semesters')}${button('Assistente de novo semestre','clone-semester')}</div><div class="grid grid-3">${items('semesters').map(x=>`<article class="card"><h3>${esc(x.title)}</h3><p>${dateLabel(x.startDate)} — ${dateLabel(x.endDate)}</p>${x.id===state.snapshot.settings.activeSemesterId?'<span class="badge badge-success">Semestre ativo</span>':button('Tornar ativo','activate-semester',`data-id="${esc(x.id)}"`)}${button('Editar','edit',`data-entity="semesters" data-id="${esc(x.id)}"`,'ghost')}</article>`).join('')||empty('Comece criando um semestre.',adminNew('semesters'))}</div><h2>Participantes</h2><div class="table-wrap card"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Acesso</th><th></th></tr></thead><tbody>${items('members').map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${roles[x.role]}</td><td>${x.active?'Ativo':'Desativado'}</td><td>${owner()&&x.role!=='owner'?button('Gerenciar','member',`data-id="${esc(x.id)}"`,'ghost'):''}</td></tr>`).join('')}</tbody></table></div>${items('invites').length?`<h2>Convites cadastrados</h2><div class="card">${items('invites').map(x=>`<p>${esc(x.email)} · ${roles[x.role]} ${x.status==='accepted'?'· Utilizado':x.status==='revoked'?'· Revogado':'· Pendente'} ${owner()&&x.status==='pending'?button('Revogar','revoke-invite',`data-id="${esc(x.id)}"`,'ghost'):''}</p>`).join('')}</div>`:''}<h2>Histórico de alterações</h2><div class="table-wrap card"><table><thead><tr><th>Data</th><th>Ação</th><th>Responsável</th><th>Registro</th></tr></thead><tbody>${items('audit').map(x=>`<tr><td>${dateLabel(x.createdAt)}</td><td>${esc(x.action)}</td><td>${esc(x.actorName||x.actorId||x.createdBy)}</td><td>${esc(x.entity||'')} ${esc(x.recordId||x.entityId||'')}</td></tr>`).join('')||'<tr><td colspan="4">Sem alterações registradas.</td></tr>'}</tbody></table></div>${more('audit')}`;}

function modal(title,body){document.querySelector('#portal-dialog')?.remove();const d=document.createElement('dialog');d.id='portal-dialog';d.className='modal';d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${button('×','close','aria-label="Fechar"','ghost')}</div><div class="modal-body">${body}</div>`;document.body.append(d);d.addEventListener('click',e=>{if(e.target===d)d.close();});d.showModal();d.querySelector('input,select,textarea,button')?.focus();}
function options(type,entity){if(type==='eventStates')return Object.entries({planned:'Previsto',confirmed:'Confirmado',completed:'Concluído'});if(type==='status')return statuses[entity].map(x=>[x,statusLabels[x]]);if(type==='kinds')return Object.entries(kindLabels);if(type==='weekdays')return Object.entries(weekdays);if(type==='materialKinds')return Object.entries({material:'Material',notes:'Anotações',exercise:'Exercícios',reference:'Referência'});return items(type).filter(x=>x.status!=='archived').map(x=>[x.id,x.title]);}
function fieldHTML([name,label,type,required],value,entity){if(type==='checkbox')return `<label class="check full"><input type="checkbox" name="${name}" ${value?'checked':''}> ${esc(label)}</label>`;let input;if(type==='links')input=`<textarea name="${name}" rows="4" placeholder="Moodle — atividades | https://...">${esc((value||[]).map(l=>l.label+' | '+l.url).join('\n'))}</textarea><span class="form-note">Um por linha: Nome e finalidade | https://endereco (até 10)</span>`;else if(type==='textarea')input=`<textarea name="${name}" maxlength="5000" rows="4" ${required?'required':''}>${esc(value||'')}</textarea>`;else if(['semesters','subjects','teachers','events','status','kinds','weekdays','materialKinds','eventStates'].includes(type)){const mult=type==='teachers';const selected=mult?(value||[]):[value||''];const choices=options(type,entity);if(['semesters','subjects','teachers','events'].includes(type)){for(const id of selected)if(id&&!choices.some(([key])=>key===id))choices.push([id,'Vínculo atual (cadastro não carregado)']);}input=`<select name="${name}" ${mult?'multiple':''} ${required?'required':''}>${!required&&!mult?'<option value="">Não vinculado</option>':''}${choices.map(([id,t])=>`<option value="${esc(id)}" ${selected.includes(id)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;}else input=`<input name="${name}" type="${type==='money'?'number':type}" value="${esc(type==='money'&&value?Number(value)/100:value||'')}" ${type==='money'?'min="0.01" step="0.01"':type==='text'?'maxlength="120"':''} ${required?'required':''}>`;return `<label class="field ${['textarea','links'].includes(type)?'full':''}">${esc(label)}${required?' *':''}${input}</label>`;}
function saveForm(entity,record={},meta={}){const initial={semesterId:state.semester||state.snapshot.settings.activeSemesterId,status:'published',subjectId:state.subject,kind:'assignment',eventState:'confirmed',category:entity==='materials'?'material':'Comunicado',...record};return `<form data-form="save" data-entity="${entity}" data-id="${esc(meta.id||record.id||'')}" data-version="${record.version||0}" ${meta.reviewId?`data-review="${esc(meta.reviewId)}" data-review-version="${meta.reviewVersion}"`:''}><div class="form-grid">${schemas[entity].fields.map(f=>fieldHTML(f,initial[f[0]],entity)).join('')}</div>${meta.reviewId?'<label class="field">Resposta ao aluno<textarea name="reviewResponse" required>Aprovado e publicado.</textarea></label>':''}<p class="form-note">* Campos obrigatórios. Textos e links serão validados ao salvar.</p><div class="form-error error" hidden></div><div class="form-actions">${button('Cancelar','close')}<button class="btn btn-primary">${meta.reviewId?'Aprovar e publicar':'Salvar '+schemas[entity].label.toLowerCase()}</button></div></form>`;}
function edit(entity,id,duplicate=false){if(!admin())return;let record=id?{...item(entity,id)}:{};if(duplicate){delete record.id;delete record.version;record.date='';record.endDate='';record.status='draft';record.title+=' — cópia';}modal((duplicate?'Duplicar ':id?'Editar ':'Novo ')+schemas[entity].label.toLowerCase(),saveForm(entity,record));}
function detail(entity,id){const x=item(entity,id);if(!x){toast('Registro não carregado. Selecione o semestre ou atualize a página.',true);return;}const task=personal().tasks?.[id]||'todo';const read=personal().read?.[id]===x.version;modal(x.title,`<div class="metadata">${badge(x.status)} ${esc(titleFor('subjects',x.subjectId))}</div><p class="item-body">${esc(x.description||'')}</p>${entity==='events'?`<p><strong>Andamento coletivo:</strong> ${esc({planned:'Previsto',confirmed:'Confirmado',completed:'Concluído'}[x.eventState||'confirmed'])}</p>`:''}${x.date?`<p><strong>Data:</strong> ${dateLabel(x.date)} ${esc(x.time||'Horário não informado')}</p>`:''}${x.location?`<p><strong>Local:</strong> ${esc(x.location)}</p>`:''}${link(x.sourceUrl||x.platformUrl)}${x.changeReason?`<div class="notice">Motivo da alteração: ${esc(x.changeReason)}</div>`:''}${entity==='events'?`<label class="field">Meu andamento<select data-task="${esc(id)}">${['todo','doing','done'].map(s=>`<option value="${s}" ${s===task?'selected':''}>${statusLabels[s]}</option>`).join('')}</select></label><p class="form-note">Esta marcação é privada e não comprova entrega ao professor.</p>`:''}${entity==='notices'&&x.important?`<div class="actions">${button(read?'✓ Leitura confirmada':'Confirmar leitura','read',`data-id="${esc(id)}" ${read?'disabled':''}`,'primary')}${admin()?button('Ver confirmações','reads',`data-id="${esc(id)}"`):''}</div>`:''}<div class="actions">${['events','notices','materials','groups'].includes(entity)?favorite(entity,id):''}${button('Copiar link','copy',`data-entity="${entity}" data-id="${esc(id)}"`)}${admin()?button('Editar','edit',`data-entity="${entity}" data-id="${esc(id)}"`)+(entity==='events'?button('Duplicar','duplicate',`data-entity="${entity}" data-id="${esc(id)}"`):'')+button(x.status==='archived'?'Restaurar':'Arquivar',x.status==='archived'?'restore':'archive',`data-entity="${entity}" data-id="${esc(id)}"`,'danger'):button('Solicitar correção','request',`data-type="correction" data-related="${esc(id)}"`)}</div>`);}
function requestModal(type='notice',parent='',related=''){modal('Enviar solicitação',`<p class="muted">Seu pedido será visível para você e os administradores.</p><form data-form="request" data-parent="${esc(parent)}" data-related="${esc(related)}"><div class="form-grid"><label class="field">Tipo<select name="type">${Object.entries(requestTypes).map(([k,v])=>`<option value="${k}" ${type===k?'selected':''}>${v}</option>`).join('')}</select></label>${fieldHTML(['subjectId','Matéria','subjects'],state.subject)}${fieldHTML(['title','Título','text',true],parent?'Complemento do pedido '+parent.slice(0,8):'')}${fieldHTML(['sourceUrl','Link da fonte ou comprovante privado','url'])}${fieldHTML(['description','Descrição e informações necessárias','textarea',true])}</div><p class="form-note">Para comprovantes, compartilhe o link somente com os administradores responsáveis. Não use um arquivo público com dados bancários.</p><div class="form-error error" hidden></div><div class="form-actions"><button class="btn btn-primary">Enviar para análise</button></div></form>`);}
function reviewModal(id){const x=item('requests',id);modal('Analisar solicitação',`<h3>${esc(x.title)}</h3><p class="item-body">${esc(x.description)}</p>${link(x.sourceUrl)}<form data-form="review" data-id="${esc(id)}" data-version="${x.version}"><label class="field">Decisão<select name="status"><option value="reviewing">Assumir análise</option><option value="awaiting">Pedir complemento</option><option value="rejected">Recusar</option><option value="cancelled">Cancelar</option>${['correction','finance','support'].includes(x.type)?'<option value="approved">Concluir sem criar publicação</option>':''}</select></label><label class="field">Resposta<textarea name="response" required maxlength="3000"></textarea></label><p class="form-note">Concluir sem publicação serve para ajuda, correções resolvidas e conferência do caixa. Registrar um pagamento exige o lançamento no Caixa.</p><div class="form-error error" hidden></div><button class="btn btn-primary">Salvar resposta</button></form>${['notice','event','material','group'].includes(x.type)?`<hr><h3>Aprovar criando uma publicação</h3><div class="actions">${['notices','events','materials','groups'].map(e=>button(schemas[e].label,'publish-request',`data-id="${esc(id)}" data-entity="${e}"`)).join('')}</div>`:''}`);}
function ledgerModal(){modal('Registrar movimento do caixa',`<form data-form="ledger"><div class="form-grid"><label class="field">Tipo<select name="type"><option value="income">Entrada</option><option value="expense">Saída</option></select></label>${fieldHTML(['date','Data','date',true],today())}${fieldHTML(['title','Descrição curta','text',true])}${fieldHTML(['amountCents','Valor em reais','money',true])}${fieldHTML(['category','Categoria','text',true])}<label class="field">Meta<select name="goalId"><option value="">Sem meta</option>${items('goals').map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select></label><label class="field">Contribuinte privado<select name="contributorId"><option value="">Não vinculado</option>${items('members').map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label>${fieldHTML(['receiptUrl','Link privado do comprovante','url'])}${fieldHTML(['description','Observação pública sem dados bancários','textarea'])}</div><p class="form-note">Confira o recebimento ou a despesa antes de salvar. Correções serão feitas por estorno.</p><div class="form-error error" hidden></div><button class="btn btn-primary">Confirmar registro</button></form>`);}
function settingsModal(){const x=state.snapshot.settings;modal('Configurações da turma',`<form data-form="settings"><div class="form-grid">${[['title','Nome do portal','text',true],['course','Curso','text',true],['university','Universidade','text'],['activeSemesterId','Semestre ativo','semesters'],['helpText','Orientações e contato dos administradores','textarea']].map(f=>fieldHTML(f,x[f[0]])).join('')}</div><div class="form-error error" hidden></div><button class="btn btn-primary">Salvar configurações</button></form>`);}
async function sessionCall(action,payload){const epoch=state.epoch,service=state.service;const result=await service.call(action,payload);if(epoch!==state.epoch||service!==state.service){const error=new Error('A sessão mudou. Entre novamente para continuar.');error.code='session-changed';throw error;}return result;}
async function mutate(action,payload,source){const op=source?.dataset.operationId||uid();if(source)source.dataset.operationId=op;const result=await sessionCall(action,{...payload,operationId:op});if(source)delete source.dataset.operationId;return result;}
async function savePersonal(changes,source){await mutate('personal',{data:{favorites:personal().favorites||[],tasks:personal().tasks||{},read:personal().read||{},preferences:personal().preferences||{},...changes}},source);await load();}

document.addEventListener('click',async event=>{
 const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,e=b.dataset.entity;
 try{
 if(a==='close'){document.querySelector('dialog')?.close();return;}
 if(a==='menu'){document.querySelector('.sidebar')?.classList.toggle('open');return;}
 if(a==='demo'){state.epoch++;state.loading=false;state.service?.unsubscribe?.();sessionStorage.setItem('portal-mode','demo');state.demo=true;state.semester='';state.snapshot=null;state.service=new DemoService();state.user={emailVerified:true};location.hash='#/home';await load(true);return;}
 if(a==='logout'){state.epoch++;state.loading=false;state.snapshot=null;state.semester='';state.search='';state.subject='';document.querySelector('dialog')?.close();document.body.dataset.theme='light';if(state.demo){sessionStorage.removeItem('portal-mode');state.demo=false;loginView();if(configured)await startFirebase();}else{await state.service.logout();loginView();}return;}
 if(a==='google'){await state.service.google();return;}
 if(a==='signup'){if(!configured){toast('Configure o Firebase conforme LEIA-ME.',true);return;}modal('Criar minha conta',`<form data-form="signup">${fieldHTML(['name','Seu nome','text',true])}${fieldHTML(['email','E-mail autorizado','email',true])}<label class="field">Senha<input name="password" type="password" required minlength="8" autocomplete="new-password"></label><p>Seu e-mail precisará ser verificado. Criar conta não dispensa convite da turma.</p><div class="form-error error" hidden></div><button class="btn btn-primary">Criar conta e verificar e-mail</button></form>`);return;}
 if(a==='reset'){if(!configured){toast('Configure o Firebase primeiro.',true);return;}modal('Recuperar acesso',`<form data-form="reset">${fieldHTML(['email','E-mail','email',true])}<div class="form-error error" hidden></div><button class="btn btn-primary">Enviar recuperação</button></form>`);return;}
 if(a==='retry'){state.user=await state.service.reload();if(state.user.emailVerified)await load(true);else gateView('Seu e-mail ainda não foi confirmado. Abra o link recebido.');return;}
 if(a==='resend'){await state.service.resend();toast('Novo e-mail de verificação enviado.');return;}
 if(!state.snapshot)return;
 if(a==='edit'){edit(e,id);return;}
 if(a==='duplicate'){edit(e,id,true);return;}
 if(a==='detail'){detail(e,id);return;}
 if(a==='request'){requestModal(b.dataset.type,b.dataset.parent,b.dataset.related);return;}
 if(a==='review'){reviewModal(id);return;}
 if(a==='publish-request'){const r=item('requests',id);modal('Revisar e publicar',saveForm(e,{title:r.title,description:r.description,semesterId:r.semesterId,subjectId:r.subjectId,sourceUrl:r.sourceUrl,authorName:r.authorName},{reviewId:r.id,reviewVersion:r.version}));return;}
 if(a==='ledger'){ledgerModal();return;}
 if(a==='clone-semester'){modal('Preparar novo semestre',`<form data-form="clone-semester"><p>Copie matérias e horários escolhidos do semestre que você está consultando. Revise o resultado antes de torná-lo ativo.</p><div class="form-grid">${fieldHTML(['title','Nome do novo semestre','text',true])}${fieldHTML(['startDate','Início','date',true])}${fieldHTML(['endDate','Fim','date',true])}</div><h3>Matérias que serão copiadas</h3>${items('subjects').filter(x=>x.status==='published').map(x=>`<label class="check"><input type="checkbox" name="cloneSubject" value="${esc(x.id)}" checked> ${esc(x.title)}</label>`).join('')}<label class="check"><input name="copySchedules" type="checkbox" checked> Copiar horários das matérias selecionadas</label><p class="form-note">Eventos, avisos, materiais e caixa não são copiados.</p><div class="form-error error" hidden></div><button class="btn btn-primary">Criar semestre para revisão</button></form>`);return;}

 if(a==='settings'){settingsModal();return;}
 if(a==='invite'){modal('Convidar integrante',`<form data-form="invite">${fieldHTML(['name','Nome','text',true])}${fieldHTML(['email','E-mail','email',true])}<label class="field">Perfil<select name="role"><option value="student">Aluno</option><option value="admin">Administrador</option></select></label><p class="form-note">O convite autoriza este e-mail. Compartilhe o endereço do portal com o colega; o sistema não envia convite por e-mail.</p><div class="form-error error" hidden></div><button class="btn btn-primary">Autorizar entrada</button></form>`);return;}
 if(a==='member'){const m=item('members',id);if(m.role==='owner'){toast('O responsável principal é definido no Firebase Console.');return;}modal('Gerenciar '+m.name,`<form data-form="member" data-id="${esc(id)}"><label class="field">Perfil<select name="role">${Object.entries(roles).filter(([k])=>k!=='owner').map(([k,v])=>`<option value="${k}" ${m.role===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="check"><input name="active" type="checkbox" ${m.active?'checked':''}> Acesso ativo</label><div class="form-error error" hidden></div><button class="btn btn-primary">Salvar acesso</button></form>`);return;}
 if(a==='reverse'){modal('Estornar movimento',`<form data-form="reverse" data-id="${esc(id)}"><p>${esc(item('ledger',id).title)} · ${money(item('ledger',id).deltaCents)}</p>${fieldHTML(['reason','Motivo do estorno','textarea',true])}<div class="form-error error" hidden></div><button class="btn btn-danger">Confirmar estorno</button></form>`);return;}
 if(a==='month'){if(state.calendarView==='week'){state.weekStart=shiftDay(state.weekStart,7*Number(b.dataset.step));renderContent();return;}const [y,m]=state.month.split('-').map(Number);state.month=new Date(Date.UTC(y,m-1+Number(b.dataset.step),1)).toISOString().slice(0,7);renderContent();return;}
 if(a==='month-today'){state.weekStart=shiftDay(today(),-((new Date(today()+'T12:00:00Z').getUTCDay()+6)%7));state.month=today().slice(0,7);renderContent();return;}
 if(a==='calendar-mode'){state.calendarView=state.calendarView==='month'?'list':'month';renderContent();return;}
 if(a==='subject'){state.subject=id;state.route='subjects';location.hash='#/subjects';renderContent();return;}
 if(a==='ics'){download('calendario-turma.ics',toICS(visible('events')),'text/calendar;charset=utf-8');toast('Calendário exportado. Mudanças futuras exigem nova exportação.');return;}
 if(a==='csv'){const rows=[['Data','Descrição','Categoria','Valor em reais','Meta'],...visible('ledger').filter(x=>!state.ledgerMonth||x.date.startsWith(state.ledgerMonth)).map(x=>[x.date,x.title,x.category,(x.deltaCents/100).toFixed(2),titleFor('goals',x.goalId)])];download('caixa-turma.csv',toCSV(rows),'text/csv;charset=utf-8');toast('Lista carregada exportada. Use Carregar mais para incluir registros anteriores.');return;}
 if(a==='copy'){await navigator.clipboard.writeText(location.href.split('#')[0]+`#/${e}/${id}`);toast('Link copiado. O destinatário precisa de acesso à turma.');return;}
 if(a==='reads'){const n=item('notices',id);if(!state.demo){const response=await sessionCall('list',{entity:'noticeReads',noticeId:id});state.snapshot.noticeReads=response.items;}const reads=(state.snapshot.noticeReads||[]).filter(x=>x.noticeId===id&&x.version===n.version);modal('Confirmações de leitura',`<p>${reads.length} confirmação(ões) da versão atual.</p>${reads.map(x=>`<p>✓ ${esc(x.memberName||x.memberId)}</p>`).join('')||'<p>Ninguém confirmou esta versão ainda.</p>'}`);return;}
 b.disabled=true;
 if(a==='clear-filters'){state.search='';state.subject='';state.category='';state.fromDate='';state.toDate='';state.showArchive=false;render();}
 if(a==='reset-preferences'){await savePersonal({preferences:{theme:'light',subjectId:'',initialView:'home'}},b);state.subject='';render();toast('Preferências restauradas.');}
 if(a==='refresh')await load(false,true);
 if(a==='more'){const r=await sessionCall('list',{entity:e,semesterId:state.semester,cursor:state.snapshot.more[e],upcoming:e==='events'&&state.route==='home'});const byId=new Map(items(e).map(x=>[x.id,x]));r.items.forEach(x=>byId.set(x.id,x));state.snapshot.data[e]=[...byId.values()];state.snapshot.more[e]=r.cursor;if(r.goalTotals)state.snapshot.goalTotals={...state.snapshot.goalTotals,...r.goalTotals};render();}
 if(a==='favorite'){const key=e+'/'+id;const favs=new Set(personal().favorites||[]);favs.has(key)?favs.delete(key):favs.add(key);await savePersonal({favorites:[...favs]},b);document.querySelector('dialog')?.close();toast('Favoritos atualizados.');}
 if(a==='read'){await savePersonal({read:{...personal().read,[id]:item('notices',id).version}},b);document.querySelector('dialog')?.close();toast('Leitura confirmada.');}
 if(a==='theme')await savePersonal({preferences:{...personal().preferences,theme:personal().preferences?.theme==='dark'?'light':'dark'}},b);
 if(['archive','restore'].includes(a)){if(confirm(a==='archive'?'Arquivar este registro? Ele ficará fora da visualização dos alunos.':'Restaurar este registro?')){await mutate(a,{entity:e,id,expectedVersion:item(e,id).version},b);document.querySelector('dialog')?.close();await load();}}
 if(a==='activate-semester'){await mutate('settings',{data:{...state.snapshot.settings,activeSemesterId:id}},b);state.semester=id;await load();toast('Semestre ativo atualizado.');}
 if(a==='backup'){if(confirm('A exportação contém solicitações e comprovantes privados. Favoritos e checklists pessoais não são incluídos. Guarde em local protegido. Exportar?')){const backup=await sessionCall('backup',{});download('backup-turma-'+today()+'.json',JSON.stringify(backup,null,2),'application/json');toast('Backup exportado.');}}
 if(a==='revoke-invite'){if(confirm('Revogar este convite? A conta ainda não vinculada não poderá entrar.')){await mutate('revokeInvite',{id},b);await load();toast('Convite revogado.');}}
 if(a==='reset-demo'){if(confirm('Reiniciar todos os dados fictícios desta demonstração?')){state.service.reset();state.semester='';await load();}}
 }catch(err){toast(friendlyError(err),true);}finally{b.disabled=false;}
});

document.addEventListener('submit',async ev=>{
 const f=ev.target;if(!(f instanceof HTMLFormElement))return;ev.preventDefault();const btn=f.querySelector('button[type="submit"],button:not([type])');if(btn)btn.disabled=true;const vals=Object.fromEntries(new FormData(f));const errEl=f.querySelector('.form-error');if(errEl)errEl.hidden=true;
 try{
 if(f.id==='login-form'){await state.service.login(vals.email,vals.password);return;}
 const type=f.dataset.form;
 if(type==='signup'){await state.service.signup(vals.name,vals.email,vals.password);document.querySelector('dialog')?.close();gateView('Conta criada. Confirme seu e-mail no link que enviamos.');return;}
 if(type==='reset'){await state.service.reset(vals.email);document.querySelector('dialog')?.close();toast('Se houver conta para este e-mail, você receberá as instruções.');return;}
 if(type==='save'){
 const e=f.dataset.entity,d={};for(const [name,,kind] of schemas[e].fields){d[name]=kind==='checkbox'?f.elements[name].checked:kind==='teachers'?[...f.elements[name].selectedOptions].map(x=>x.value):kind==='money'?Math.round(Number(vals[name])*100):kind==='links'?(vals[name]||'').split('\n').filter(l=>l.trim()).map(l=>{const at=l.indexOf('|');if(at<1)throw Error('Use Nome | https://endereco em cada plataforma.');return {label:l.slice(0,at).trim(),url:l.slice(at+1).trim()};}):vals[name]||'';}
 if(e==='events'){
 if(d.endDate&&d.endDate<d.date)throw Error('A data de término deve ser igual ou posterior à data inicial.');
 if(d.allDay)d.time='';
 const existing=f.dataset.id?item(e,f.dataset.id):null;if(existing&&(existing.date!==d.date||existing.time!==d.time)&&!d.changeReason.trim())throw Error('Informe o motivo da mudança de prazo.');
 const duplicate=items('events').some(x=>x.id!==f.dataset.id&&x.subjectId===d.subjectId&&x.date===d.date&&x.title.toLocaleLowerCase().trim()===d.title.toLocaleLowerCase().trim());if(duplicate&&!confirm('Já existe evento com mesmo título, matéria e data. Confirmar outro evento?'))return;
 const conflict=items('events').some(x=>x.id!==f.dataset.id&&x.status==='published'&&x.date===d.date&&x.time===d.time&&['exam','presentation'].includes(x.kind));if(conflict&&!confirm('Existe uma prova ou apresentação no mesmo horário. Publicar mesmo assim?'))return;
 }
 if(f.dataset.review)await mutate('review',{id:f.dataset.review,expectedVersion:Number(f.dataset.reviewVersion),status:'approved',response:vals.reviewResponse,entity:e,data:d},f);
 else await mutate('save',{entity:e,...(f.dataset.id?{id:f.dataset.id,expectedVersion:Number(f.dataset.version)}:{}),data:d},f);
 }else if(type==='preferences'){await savePersonal({preferences:{...personal().preferences,initialView:vals.initialView,subjectId:vals.subjectId}},f);state.subject=vals.subjectId;}
 else if(type==='clone-semester'){const subjectIds=[...f.querySelectorAll('[name=cloneSubject]:checked')].map(x=>x.value);const result=await mutate('cloneSemester',{data:{title:vals.title,startDate:vals.startDate,endDate:vals.endDate,sourceSemesterId:state.semester,subjectIds,copySchedules:f.elements.copySchedules.checked}},f);state.semester=result.id;}
 else if(type==='request'){await mutate('request',{data:{...vals,semesterId:state.semester||state.snapshot.settings.activeSemesterId,relatedId:f.dataset.related||'',parentId:f.dataset.parent||''}},f);}
 else if(type==='review')await mutate('review',{id:f.dataset.id,expectedVersion:Number(f.dataset.version),...vals},f);
 else if(type==='ledger')await mutate('ledger',{data:{...vals,amountCents:Math.round(Number(vals.amountCents)*100)}},f);
 else if(type==='reverse')await mutate('reverse',{id:f.dataset.id,reason:vals.reason},f);
 else if(type==='settings'){await mutate('settings',{data:vals},f);state.semester=vals.activeSemesterId;}
 else if(type==='invite')await mutate('invite',vals,f);
 else if(type==='member')await mutate('member',{id:f.dataset.id,role:vals.role,active:f.elements.active.checked},f);
 document.querySelector('dialog')?.close();await load();toast('Alteração salva com sucesso.');
 }catch(err){const msg=friendlyError(err);if(errEl){errEl.textContent=msg;errEl.hidden=false;}else toast(msg,true);}finally{if(btn)btn.disabled=false;}
});
document.addEventListener('input',ev=>{if(ev.target.id==='global-search'){state.search=ev.target.value;renderContent();}});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.id==='semester-select'){state.epoch++;state.loading=false;state.semester=el.value;state.subject='';state.category='';state.fromDate='';state.toDate='';await load(true);}if(el.id==='calendar-view'){state.calendarView=el.value;renderContent();}if(el.id==='category-filter'){state.category=el.value;renderContent();}if(el.id==='from-date'){state.fromDate=el.value;renderContent();}if(el.id==='to-date'){state.toDate=el.value;renderContent();}if(el.id==='subject-filter'){state.subject=el.value;renderContent();}if(el.id==='archive-filter'){state.showArchive=el.checked;renderContent();}if(el.id==='request-kind'){state.requestKind=el.value;renderContent();}if(el.id==='request-owner'){state.requestOwner=el.value;renderContent();}if(el.id==='request-status'){state.requestStatus=el.value;renderContent();}if(el.id==='ledger-month'){state.ledgerMonth=el.value;renderContent();}if(el.id==='demo-role'){state.epoch++;state.loading=false;state.service.setRole(el.value);await load();}if(el.dataset.task){await savePersonal({tasks:{...personal().tasks,[el.dataset.task]:el.value}},el);toast('Seu andamento foi atualizado.');}}catch(e){toast(friendlyError(e),true);}});
window.addEventListener('hashchange',async()=>{document.querySelector('dialog')?.close();if(state.service&&state.user?.emailVerified){state.epoch++;state.loading=false;await load(true);}});
window.addEventListener('offline',()=>toast('Você está sem conexão. Novas alterações precisam de internet.',true));
// Atualização explícita economiza a cota Spark e preserva páginas já carregadas.

async function init(){if(sessionStorage.getItem('portal-mode')==='demo'){state.demo=true;state.service=new DemoService();state.user={emailVerified:true};await load(true);}else if(configured){loading('Preparando acesso…');try{await startFirebase();}catch(e){loginView(friendlyError(e));}}else loginView();}
init();
